// WorkspaceServiceHandler is an implementation of the devopus.workspace.v1.WorkspaceService
// service.
type WorkspaceServiceHandler interface {
	// ListServiceTypes is the catalog of service types (internal/catalog): what
	// 'devopus service add' and the web interface offer.
	ListServiceTypes(context.Context, *connect.Request[v1.ListServiceTypesRequest]) (*connect.Response[v1.ListServiceTypesResponse], error)
	// CreateWorkspace makes a workspace; its creator is its admin.
	CreateWorkspace(context.Context, *connect.Request[v1.CreateWorkspaceRequest]) (*connect.Response[v1.CreateWorkspaceResponse], error)
	// ListWorkspaces lists the workspaces the user is a member of on this server.
	ListWorkspaces(context.Context, *connect.Request[v1.ListWorkspacesRequest]) (*connect.Response[v1.ListWorkspacesResponse], error)
	// GetWorkspace describes a workspace and what the caller may do in it.
	GetWorkspace(context.Context, *connect.Request[v1.GetWorkspaceRequest]) (*connect.Response[v1.GetWorkspaceResponse], error)
	RenameWorkspace(context.Context, *connect.Request[v1.RenameWorkspaceRequest]) (*connect.Response[v1.RenameWorkspaceResponse], error)
	// TransferWorkspace makes another member the admin; the old admin stays a teamlead.
	TransferWorkspace(context.Context, *connect.Request[v1.TransferWorkspaceRequest]) (*connect.Response[v1.TransferWorkspaceResponse], error)
	// DeleteWorkspace removes a workspace with its projects, members and invites.
	DeleteWorkspace(context.Context, *connect.Request[v1.DeleteWorkspaceRequest]) (*connect.Response[v1.DeleteWorkspaceResponse], error)
	// ListAudit is the workspace's log: who changed members, roles and permissions.
	ListAudit(context.Context, *connect.Request[v1.ListAuditRequest]) (*connect.Response[v1.ListAuditResponse], error)
	// CreateProject adds a project; a teamlead who creates it leads it.
	CreateProject(context.Context, *connect.Request[v1.CreateProjectRequest]) (*connect.Response[v1.CreateProjectResponse], error)
	// ListProjects lists the workspace's projects with the caller's role in each.
	ListProjects(context.Context, *connect.Request[v1.ListProjectsRequest]) (*connect.Response[v1.ListProjectsResponse], error)
	// DeleteProject removes a project with its settings and roles: the admin or a
	// teamlead of the project; a granted project.configure is not enough.
	DeleteProject(context.Context, *connect.Request[v1.DeleteProjectRequest]) (*connect.Response[v1.DeleteProjectResponse], error)
	// GetProjectConfig is a version of a project's settings: the current one by default.
	GetProjectConfig(context.Context, *connect.Request[v1.GetProjectConfigRequest]) (*connect.Response[v1.GetProjectConfigResponse], error)
	// ListProjectVersions is the history of a project's settings, newest first.
	ListProjectVersions(context.Context, *connect.Request[v1.ListProjectVersionsRequest]) (*connect.Response[v1.ListProjectVersionsResponse], error)
	// UpdateProjectSettings changes the domain and the policies of a project.
	UpdateProjectSettings(context.Context, *connect.Request[v1.UpdateProjectSettingsRequest]) (*connect.Response[v1.UpdateProjectSettingsResponse], error)
	// RollbackProject makes an older version current again, as a new version.
	RollbackProject(context.Context, *connect.Request[v1.RollbackProjectRequest]) (*connect.Response[v1.RollbackProjectResponse], error)
	// PutApp adds or replaces an application of a project.
	PutApp(context.Context, *connect.Request[v1.PutAppRequest]) (*connect.Response[v1.PutAppResponse], error)
	// RemoveApp removes an application; services attached to it are detached, which
	// needs services.manage too.
	RemoveApp(context.Context, *connect.Request[v1.RemoveAppRequest]) (*connect.Response[v1.RemoveAppResponse], error)
	// PutService adds or replaces a service of a project, with the applications it is
	// attached to.
	PutService(context.Context, *connect.Request[v1.PutServiceRequest]) (*connect.Response[v1.PutServiceResponse], error)
	RemoveService(context.Context, *connect.Request[v1.RemoveServiceRequest]) (*connect.Response[v1.RemoveServiceResponse], error)
	// CreateServer adds a server and gives the one-time code its agent joins with.
	// Needs servers.manage in every project it is to run (the admin's for none).
	CreateServer(context.Context, *connect.Request[v1.CreateServerRequest]) (*connect.Response[v1.CreateServerResponse], error)
	// JoinServer trades the one-time code for the server's device token.
	JoinServer(context.Context, *connect.Request[v1.JoinServerRequest]) (*connect.Response[v1.JoinServerResponse], error)
	ListServers(context.Context, *connect.Request[v1.ListServersRequest]) (*connect.Response[v1.ListServersResponse], error)
	// SetServerProjects sets which projects a server runs.
	SetServerProjects(context.Context, *connect.Request[v1.SetServerProjectsRequest]) (*connect.Response[v1.SetServerProjectsResponse], error)
	// RemoveServer revokes a server's token; its agent stops the projects.
	RemoveServer(context.Context, *connect.Request[v1.RemoveServerRequest]) (*connect.Response[v1.RemoveServerResponse], error)
	// RegisterSigningKey records the signing key of one of the caller's devices. A new
	// key for the device needs a new certificate.
	RegisterSigningKey(context.Context, *connect.Request[v1.RegisterSigningKeyRequest]) (*connect.Response[v1.RegisterSigningKeyResponse], error)
	// SetTrustRoot makes a signing key of the admin's device the workspace's root of
	// trust. Once: agents pin the first root and take no other.
	SetTrustRoot(context.Context, *connect.Request[v1.SetTrustRootRequest]) (*connect.Response[v1.SetTrustRootResponse], error)
	// ListSigningKeys shows the root and every device's signing key, certified or not.
	ListSigningKeys(context.Context, *connect.Request[v1.ListSigningKeysRequest]) (*connect.Response[v1.ListSigningKeysResponse], error)
	// CertifySigningKey stores the root's certificate for a device, made on the admin's
	// device that holds the root.
	CertifySigningKey(context.Context, *connect.Request[v1.CertifySigningKeyRequest]) (*connect.Response[v1.CertifySigningKeyResponse], error)
	// SignVersion stores the author's signature of a version of a project's settings.
	SignVersion(context.Context, *connect.Request[v1.SignVersionRequest]) (*connect.Response[v1.SignVersionResponse], error)
	// GetSecretsKey is the workspace's current public key, and its private key wrapped
	// for one of the caller's devices if it has reached it.
	GetSecretsKey(context.Context, *connect.Request[v1.GetSecretsKeyRequest]) (*connect.Response[v1.GetSecretsKeyResponse], error)
	// RegisterDeviceKey records the public key of one of the caller's devices: the
	// workspace's key is wrapped for it.
	RegisterDeviceKey(context.Context, *connect.Request[v1.RegisterDeviceKeyRequest]) (*connect.Response[v1.RegisterDeviceKeyResponse], error)
	// CreateSecretsKey sets the workspace's first key, made on the admin's device.
	CreateSecretsKey(context.Context, *connect.Request[v1.CreateSecretsKeyRequest]) (*connect.Response[v1.CreateSecretsKeyResponse], error)
	// ProvideKeyWraps delivers the workspace's key to devices waiting for it, wrapped
	// on a device that holds it: an admin's or a teamlead's.
	ProvideKeyWraps(context.Context, *connect.Request[v1.ProvideKeyWrapsRequest]) (*connect.Response[v1.ProvideKeyWrapsResponse], error)
	// PrepareRotation gives the admin's device what a rotation re-encrypts: every
	// secret, sealed, and the devices that are to keep the key.
	PrepareRotation(context.Context, *connect.Request[v1.PrepareRotationRequest]) (*connect.Response[v1.PrepareRotationResponse], error)
	// RotateSecretsKey replaces the key: every secret re-encrypted and the key wrapped
	// for the devices still in the workspace, all on the admin's device.
	RotateSecretsKey(context.Context, *connect.Request[v1.RotateSecretsKeyRequest]) (*connect.Response[v1.RotateSecretsKeyResponse], error)
	// SetSecret stores a secret of a project, encrypted to the workspace's key.
	SetSecret(context.Context, *connect.Request[v1.SetSecretRequest]) (*connect.Response[v1.SetSecretResponse], error)
	// ListSecrets names a project's secrets; values only agents decrypt.
	ListSecrets(context.Context, *connect.Request[v1.ListSecretsRequest]) (*connect.Response[v1.ListSecretsResponse], error)
	RemoveSecret(context.Context, *connect.Request[v1.RemoveSecretRequest]) (*connect.Response[v1.RemoveSecretResponse], error)
	// CreateInvite invites an email with a role: the admin invites teamleads and
	// developers, a teamlead invites developers into the projects they lead.
	CreateInvite(context.Context, *connect.Request[v1.CreateInviteRequest]) (*connect.Response[v1.CreateInviteResponse], error)
	// ListInvites lists open invites: all for the admin, their own for a teamlead.
	ListInvites(context.Context, *connect.Request[v1.ListInvitesRequest]) (*connect.Response[v1.ListInvitesResponse], error)
	RevokeInvite(context.Context, *connect.Request[v1.RevokeInviteRequest]) (*connect.Response[v1.RevokeInviteResponse], error)
	// AcceptInvite joins the workspace of an invite to the caller's email.
	AcceptInvite(context.Context, *connect.Request[v1.AcceptInviteRequest]) (*connect.Response[v1.AcceptInviteResponse], error)
	ListMembers(context.Context, *connect.Request[v1.ListMembersRequest]) (*connect.Response[v1.ListMembersResponse], error)
	// GrantPermission gives a developer of a project a permission on top of the role.
	GrantPermission(context.Context, *connect.Request[v1.GrantPermissionRequest]) (*connect.Response[v1.GrantPermissionResponse], error)
	RevokePermission(context.Context, *connect.Request[v1.RevokePermissionRequest]) (*connect.Response[v1.RevokePermissionResponse], error)
	// RemoveFromProject takes a member out of a project: a teamlead removes developers.
	RemoveFromProject(context.Context, *connect.Request[v1.RemoveFromProjectRequest]) (*connect.Response[v1.RemoveFromProjectResponse], error)
	// RemoveMember removes a member from the workspace; their access ends at once.
	RemoveMember(context.Context, *connect.Request[v1.RemoveMemberRequest]) (*connect.Response[v1.RemoveMemberResponse], error)
}

